    """Replace the marker color with 0 and fill background with its paired color."""
    marker_colors = {value for row in grid for value in row if value != 0}
    if len(marker_colors) != 1:
        raise ValueError("expected one nonzero marker color")
    marker = next(iter(marker_colors))
    fill = {3: 1, 8: 2}[marker]
    return [[0 if value == marker else fill for value in row] for row in grid]
